import{_ as e,o as l,c as o,a0 as t}from"./chunks/framework.DhQjJcnt.js";const P=JSON.parse('{"title":"路线图","description":"","frontmatter":{},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md","lastUpdated":null}'),r={name:"roadmap.md"};function i(n,a,s,d,c,h){return l(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="路线图" tabindex="-1">路线图 <a class="header-anchor" href="#路线图" aria-label="Permalink to &quot;路线图&quot;">​</a></h1><p>当前版本聚焦「简单、健壮、够用」。以下按优先级列出计划中的能力。</p><h2 id="近期" tabindex="-1">近期 <a class="header-anchor" href="#近期" aria-label="Permalink to &quot;近期&quot;">​</a></h2><ul><li>[ ] <strong>并发多连接复用</strong>：同一隧道同时承载多条本地 TCP 连接（当前为顺序复用）</li><li>[ ] <strong>WebSocket 实时信令</strong>：房主即时感知访客加入，替代轮询（降低直连建立延迟）</li><li>[ ] <strong>UPnP 自动端口映射</strong>：打洞前的补充手段，路由器支持时直接映射端口</li></ul><h2 id="中期" tabindex="-1">中期 <a class="header-anchor" href="#中期" aria-label="Permalink to &quot;中期&quot;">​</a></h2><ul><li>[ ] <strong>x25519 密钥交换</strong>：免口令自动协商会话密钥（替代手工 <code>--key</code>）</li><li>[ ] <strong>中继通道加密</strong>：中继路径同样提供机密性（当前 <code>--key</code> 仅作用于 P2P 直连）</li><li>[ ] <strong>多节点房间（&gt;2 人）</strong>：中心节点广播成员地址，网状 P2P</li><li>[ ] <strong>传输参数自适应</strong>：根据丢包/时延自动调整窗口、重传间隔、MTU</li></ul><h2 id="远期" tabindex="-1">远期 <a class="header-anchor" href="#远期" aria-label="Permalink to &quot;远期&quot;">​</a></h2><ul><li>[ ] <strong>平台化</strong>：Windows/macOS 安装包、开机自启、托盘图标</li><li>[ ] <strong>中继集群</strong>：多服务器中继池 + 就近选路</li><li>[ ] <strong>兼容层</strong>：接入现有协议生态（可选）</li></ul><h2 id="已实现的能力-v0-1" tabindex="-1">已实现的能力（v0.1） <a class="header-anchor" href="#已实现的能力-v0-1" aria-label="Permalink to &quot;已实现的能力（v0.1）&quot;">​</a></h2><ul><li>房间制信令（REST + UDP 探测 + TTL 过期）</li><li>UDP 打洞（PUNCH/ACK 同时握手 + 端口散布）</li><li>FRS1 可靠流（滑动窗口 + 重传 + keepalive + FIN 握手）</li><li>ChaCha20-Poly1305 端到端加密（<code>--key</code>）</li><li>顺序多连接复用（<code>--max-conns</code>）</li><li>TCP 中继回退（配对 + 双向拷贝 + 迟到直连复查）</li><li>Windows 兼容（ICMP 毒化处理）</li><li>端到端测试与真实 NAT 实测</li></ul><h2 id="贡献" tabindex="-1">贡献 <a class="header-anchor" href="#贡献" aria-label="Permalink to &quot;贡献&quot;">​</a></h2><p>欢迎提交 PR。开发指引见<a href="./develop">开发与测试</a>，协议细节见<a href="./protocol">协议规范</a>。</p>',12)])])}const p=e(r,[["render",i]]);export{P as __pageData,p as default};
